package co.fcv.citas.config; import java.util.List; import org.springframework.context.annotation.*; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.web.SecurityFilterChain; import org.springframework.web.cors.CorsConfiguration; import org.springframework.web.cors.CorsConfigurationSource; import org.springframework.web.cors.UrlBasedCorsConfigurationSource;
@Configuration @EnableWebSecurity public class SecurityConfig { @Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder();} @Bean CorsConfigurationSource corsConfigurationSource(org.springframework.core.env.Environment env){var c=new CorsConfiguration();c.setAllowedOrigins(List.of(env.getProperty("app.frontend-origin","http://localhost:5173")));c.setAllowedMethods(List.of("POST","GET","OPTIONS"));c.setAllowedHeaders(List.of("Authorization","Content-Type"));var s=new UrlBasedCorsConfigurationSource();s.registerCorsConfiguration("/**",c);return s;} @Bean SecurityFilterChain security(HttpSecurity http,co.fcv.citas.auth.JwtAuthFilter jwtFilter)throws Exception{return http.csrf(c->c.disable()).cors(c->{}).addFilterBefore(jwtFilter,org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter.class).authorizeHttpRequests(a->a.requestMatchers("/api/auth/**","/actuator/health").permitAll().anyRequest().authenticated()).build();} }
